sections.content:
The event loop processes different types of callbacks in this order:

 Timers: setTimeout, setInterval

 I/O Callbacks: Completed I/O operations

 Poll: Retrieve new I/O events

 Check: setImmediate callbacks

 Close: Cleanup callbacks (like socket.on('close'))

 Note: Between each phase, Node.js runs microtasks (Promises) and process.nextTick callbacks.

Example: Event Loop Phases

console.log('1. Start');

// Next tick queue

process.nextTick(() => console.log('2. Next tick'));

// Microtask queue (Promise)

Promise.resolve().then(() => console.log('3. Promise'));

// Timer phase

setTimeout(() => console.log('4. Timeout'), 0);

// Check phase

setImmediate(() => console.log('5. Immediate'));

console.log('6. End');

Try it Yourself »

The output will be:

1. Start
6. End
2. Next tick
3. Promise
4. Timeout
5. Immediate

This shows the priority order: sync code > nextTick > Promises > Timers > Check phase.

code_examples.code:
console.log('First');

setTimeout(() => console.log('Third'), 0);

Promise.resolve().then(() => console.log('Second'));

console.log('Fourth');

sections.content:
Synchronous

 Blocks execution until complete

 Simple to understand

 Can cause delays

 Uses functions like readFileSync

 Asynchronous

 Non-blocking execution

 Better performance

 More complex to handle

 Uses callbacks, promises, or async/await

Example: Synchronous File Read

const fs = require('fs');

console.log('1. Starting sync read...');

const data = fs.readFileSync('myfile.txt', 'utf8');

console.log('2. File contents:', data);

console.log('3. Done reading file');

Run example »

Output will be in order: 1 → 2 → 3 (blocks between each step)

Example: Asynchronous File Read

const fs = require('fs');

console.log('1. Starting async read...');

fs.readFile('myfile.txt', 'utf8', (err, data) => {

  if (err) throw err;

  console.log('2. File contents:', data);

});

console.log('3. Done starting read operation');

Run example »

Output order: 1 → 3 → 2 (doesn't wait for file read to complete)

Problem: Nested Callbacks (Callback Hell)

 getUser(userId, (err, user) => {

   if (err) return handleError(err);

   getOrders(user.id, (err, orders) => {

     if (err) return handleError(err);

     processOrders(orders, (err) => {

       if (err) return handleError(err);

       console.log('All done!');

     });

   });

 });

 Solution: Use Promises

 getUser(userId)

   .then(user => getOrders(user.id))

   .then(orders => processOrders(orders))

   .then(() => console.log('All done!'))

   .catch(handleError);

 Even Better: Async/Await

 async function processUser(userId) {

   try {

     const user = await getUser(userId);

     const orders = await getOrders(user.id);

     await processOrders(orders);

     console.log('All done!');

   } catch (err) {

     handleError(err);

   }

 }

1. Promises

const fs = require('fs').promises;

console.log('1. Reading file...');

fs.readFile('myfile.txt', 'utf8')

  .then(data => {

    console.log('3. File content:', data);

  })

  .catch(err => console.error('Error:', err));

console.log('2. This runs before file is read!');

 2. Async/Await (Recommended)

async function readFiles() {

  try {

    console.log('1. Starting to read files...');

    const data1 = await fs.readFile('file1.txt', 'utf8');

    const data2 = await fs.readFile('file2.txt', 'utf8');

    console.log('2. Files read successfully!');

    return { data1, data2 };

  } catch (error) {

    console.error('Error reading files:', error);

  }

}

Do This

 // Use async/await for better readability

 async function getUserData(userId) {

   try {

     const user = await User.findById(userId);

     const orders = await Order.find({ userId });

     return { user, orders };

   } catch (error) {
     console.error('Failed to fetch user data:', error);

     throw error; // Re-throw or handle appropriately

   }

 }

 Not This

 // Nested callbacks are hard to read and maintain

 User.findById(userId, (err, user) => {

   if (err) return console.error(err);

   Order.find({ userId }, (err, orders) => {

     if (err) return console.error(err);

     // Process orders...

   });

 });

 Key Takeaways

 ✅ Use async/await for better readability

 ✅ Always handle errors with try/catch

 ✅ Run independent operations in parallel with Promise.all

 ❌ Avoid mixing sync and async code patterns

 ❌ Don't forget to await promises

 Example: Parallel Execution

 // Run multiple async operations in parallel

 async function fetchAllData() {

   try {

     const [users, products, orders] = await Promise.all([

       User.find(),

       Product.find(),

       Order.find()

     ]);

     return { users, products, orders };

   } catch (error) {

     console.error('Error fetching data:', error);

     throw error;

   }

 }

