Prevent bad code from being committed by setting up pre-commit hooks that automatically format and lint your code:

 Why use pre-commit hooks? They ensure consistent code quality across your team by automatically fixing style issues before code is committed.

Ensure code quality before commits with pre-commit hooks:

Installation

npm install --save-dev husky lint-staged

Configuration (package.json)

{

  "husky": {

    "hooks": {

      "pre-commit": "lint-staged"

    }

  }

  "lint-staged": {

    "*.{js,jsx,ts,tsx}": [

      "eslint --fix",

      "prettier --write"

    ],

    "*.{json,md,yml}": [

      "prettier --write"

    ]

  }

}

code_examples.code:
{

  "env": {

    "node": true,

    "es2021": true,

    "browser": true

  },

  "extends": [

    "eslint:recommended",

    "plugin:@typescript-eslint/recommended"

  ],

  "parser": "@typescript-eslint/parser",

  "parserOptions": {

    "ecmaVersion": 12,

    "sourceType": "module"

  },

  "plugins": ["@typescript-eslint"],

  "rules": {

    "semi": ["error", "always"],

    "quotes": ["error", "single"],

    "indent": ["error", 2],

    "no-console": "warn",

    "no-unused-vars": "warn"

  }

}

{

  "extends": [

    "eslint:recommended",

    "plugin:@typescript-eslint/recommended",

    "plugin:prettier/recommended"

  ]

}

{

  "editor.formatOnSave": true,

  "editor.codeActionsOnSave": {

    "source.fixAll.eslint": true

  },

  "eslint.validate": ["javascript", "javascriptreact", "typescript", "typescriptreact"],

  "prettier.requireConfig": true,

  "editor.defaultFormatter": "esbenp.prettier-vscode"

}

{

  "husky": {

    "hooks": {

      "pre-commit": "lint-staged"

    }

  }

  "lint-staged": {

    "*.{js,jsx,ts,tsx}": [

      "eslint --fix",

      "prettier --write"

    ],

