You can delete records from an existing table by using 
the "DELETE FROM" statement:

Example
Delete any record with the address "Mountain 21":

 let mysql = require('mysql');

 let con = mysql.createConnection({

 host: "localhost",
  user: "yourusername",

 password: "yourpassword",
  database: "mydb"
});

con.connect(function(err) {
  if (err) throw err;

 let sql = "DELETE FROM customers WHERE address = 'Mountain 21'";

 con.query(sql, function (err, result) {

 if (err) throw err;
    console.log("Number of records 
 deleted: " + result.affectedRows);
  });

 });

Run example »

Notice the WHERE clause in the DELETE syntax: The WHERE clause 
specifies which record or records that should be deleted. If you omit the WHERE 
clause, all records will be deleted!

