To delete a record, or document as it is called in MongoDB, we use the
deleteOne() method.

The first parameter of the deleteOne() method 
is a query object defining which document to delete.

Note: If the query finds more than one document, only the first 
occurrence is deleted.

Example
Delete the document with the address "Mountain 21":

 let MongoClient = require('mongodb').MongoClient;

 let url = "mongodb://localhost:27017/";

 MongoClient.connect(url, function(err, db) {
  if (err) throw err;

 let dbo = db.db("mydb");

   let myquery = { address: 'Mountain 21' };

 dbo.collection("customers").deleteOne(myquery, function(err, obj) {

 if (err) throw err;
    console.log("1 
 document deleted");
    db.close();
  });
});

 Run example »

