You can update a record, or document as it is called in MongoDB, by using 
the updateOne() method.

The first parameter of the updateOne() method 
is a query object defining which document to update.

Note: If the query finds more than one record, only the first 
occurrence is updated.

The second parameter 
is an object defining the new values of the document._id field) 
so remember to set the value of every field, otherwise the value will be left 
empty.-->

 Example
Update the document with the address "Valley 345" to name="Mickey" and 
address="Canyon 123":

 let MongoClient = require('mongodb').MongoClient;
let url = "mongodb://127.0.0.1:27017/";

MongoClient.connect(url, function(err, db) {
  if (err) throw err;

 let dbo = db.db("mydb");

 let myquery = { address: "Valley 345" };
  let newvalues = { 
 $set: {name: 
 "Mickey", address: "Canyon 123" } };
  dbo.collection("customers").updateOne(myquery, 
 newvalues, function(err, res) {
    if (err) throw err;

 console.log("1 document updated");

 db.close();
  });
});

