Let's build a simple real-time chat application using Node.js and Socket.IO.

This example doesn't require any login and demonstrates the basic functionality.

Create the Server (app.js)

Create a new file named app.js with the following content:

const express = require('express');

const http = require('http');

const { Server } = require('socket.io');

const path = require('path');

const app = express();

const server = http.createServer(app);

const io = new Server(server);

// Serve static files

app.use(express.static(path.join(__dirname, 'public')));

// Simple route

app.get('/', (req, res) => {

;  res.sendFile(path.join(__dirname, 'public', 'index.html'));

});

// Socket.IO connection handler

io.on('connection', (socket) => {

  console.log('A user connected');

  // Handle new messages

  socket.on('chat message', (msg) => {

    console.log('Message received:', msg);

    // Broadcast the message to all connected clients

      io.emit('chat message', msg);

    });

  // Handle disconnection

  socket.on('disconnect', () => {

    console.log('A user disconnected');

  });

});

const PORT = process.env.PORT || 3000;

server.listen(PORT, () => {

  console.log(`Server running on port ${PORT}`);

});

Create the Client (public/index.html)

Create a public directory and add an index.html file with this content:

<!DOCTYPE html>

<html>

<head>

  <title>Simple Chat</title>

  <style>

  body { 

    margin: 0; 

    padding: 20px; 

    font-family: Arial, sans-serif; 

  }

  #messages { 

    list-style-type: none; 

    margin: 0; 

    padding: 0; 

    margin-bottom: 20px;

    border: 1px solid #ddd;

    padding: 10px;

    height: 400px;

    overflow-y: auto;

    }

    #messages li { 

      padding: 8px 16px; 

      border-bottom: 1px solid #eee; 

    }

    #messages li:last-child { 

      border-bottom: none; 

    }

    #form { 

      display: flex; 

      margin-top: 10px; 

    }

    #input { 

      flex-grow: 1; 

      padding: 10px; 

      font-size: 16px; 

    }

    button { 

      padding: 10px 20px; 

      background: #4CAF50; 

      color: white; 

      border: none; 

      cursor: pointer; 

      margin-left: 10px;

      }

    button:hover { 

      background: #45a049; 

    }

  </style>

</head>

<body>

  <h1>Simple Chat</h1>

  <ul id="messages"></ul>

  <form id="form" action="#">

    <input id="input" autocomplete="off" placeholder="Type your message..." />

   <button>Send</button>

   </form>

  <script src="/socket.io/socket.io.js"></script>

  <script>

    const socket = io();

    const form = document.getElementById('form');

    const input = document.getElementById('input');

    const messages = document.getElementById('messages');

    // Handle form submission

    form.addEventListener('submit', (e) => {

        e.preventDefault();

        const message = input.value.trim();

        if (message) {

            // Emit the message to the server

            socket.emit('chat message', message);

                // Clear the input

                input.value = '';

            }

        });

        // Listen for incoming messages

        socket.on('chat message', (msg) => {

            const item = document.createElement('li');

            item.textContent = msg;

            messages.appendChild(item);

            // Scroll to the bottom

            messages.scrollTop = messages.scrollHeight;

        });

    </script>

</body>

</html>

Run the Application

Start the server:

 node app.js

Open your browser and navigate to http://localhost:3000

Open multiple browser windows to see the real-time updates

How It Works

 The server uses Express to serve the static files and handle the Socket.IO connection

 When a client connects, they can send messages that get broadcast to all connected clients

 The client-side JavaScript handles sending and receiving messages in real-time

Next Steps

Once you have this basic version working, you might want to add:

 Usernames for each message

 User join/leave notifications

 Different chat rooms

 Message persistence

 User authentication

 Note: This is a basic example for demonstration purposes. In a production environment, you would want to add proper error handling, input validation, and security measures.

Let's enhance our chat by adding usernames to messages. First, modify the server to handle usernames:

// In app.js, modify the connection handler

io.on('connection', (socket) => {

  console.log('A user connected');

  // Store username with socket

  socket.username = 'Anonymous';

  // Handle new messages with username

  socket.on('chat message', (msg) => {

    io.emit('chat message', {

      username: socket.username,

      message: msg,

      timestamp: new Date().toISOString()

    });

  });

  // Handle username change

  socket.on('set username', (username) => {

    const oldUsername = socket.username;

    socket.username = username || 'Anonymous';

    io.emit('user joined', {

      oldUsername: oldUsername,

      newUsername: socket.username

    });

  });

  // Handle disconnection

  socket.on('disconnect', () => {

    console.log('A user disconnected');

    io.emit('user left', { username: socket.username });

  });

});

Now, update the client to handle usernames:

<!-- Add username input at the top of the chat -->

<div id="username-container">

    <input type="text" id="username-input" placeholder="Enter your username" />

    <button id="set-username">Set Username</button>

</div>

<script>

    // Add username handling

    const usernameInput = document.getElementById('username-input');

    const setUsernameBtn = document.getElementById('set-username');

    let currentUsername = 'Anonymous';

    setUsernameBtn.addEventListener('click', () => {

        const newUsername = usernameInput.value.trim();

        if (newUsername) {

            socket.emit('set username', newUsername);

            currentUsername = newUsername;

            usernameInput.value = '';

        }

    });

    // Update message display to show usernames

    socket.on('chat message', (data) => {

        const item = document.createElement('li');

        item.innerHTML = `<strong>${data.username}:</strong> ${data.message}`;

        messages.appendChild(item);

        messages.scrollTop = messages.scrollHeight;

    });

    // Handle user join notifications

    socket.on('user joined', (data) => {

        const item = document.createElement('li');

        item.className = 'system-message';

        if (data.oldUsername === 'Anonymous') {

            item.textContent = `${data.newUsername} has joined the chat`;

        } else {

            item.textContent = `${data.oldUsername} is now known as ${data.newUsername}`;

        }

        messages.appendChild(item);

        messages.scrollTop = messages.scrollHeight;

    });

    // Handle user leave notifications

    socket.on('user left', (data) => {

        const item = document.createElement('li');

        item.className = 'system-message';

        item.textContent = `${data.username} has left the chat`;

        messages.appendChild(item);

        messages.scrollTop = messages.scrollHeight;

    });

</script>

<style>

.system-message {

    color: #666;

