Let's add the ability to create and join different chat rooms. First, update the server:

// In app.js, add room handling

const rooms = new Set(['general', 'random']);

io.on('connection', (socket) => {

  // ... existing code ...

  // Join a room

  socket.on('join room', (room) => {

    // Leave all rooms except the default one

    socket.rooms.forEach(r => {

      if (r !== socket.id) {

        socket.leave(r);

        socket.emit('left room', r);

      }

    });

    // Join the new room

    socket.join(room);

    socket.emit('joined room', room);

    // Notify others in the room

    socket.to(room).emit('room message', {

      username: 'System',

      message: `${socket.username} has joined the room`,

      timestamp: new Date().toISOString()

    });

  });

  // Handle room creation

  socket.on('create room', (roomName) => {

    if (!rooms.has(roomName)) {

      rooms.add(roomName);

      io.emit('room created', roomName);

    }

  });

  // Modify message handler to send to room

  socket.on('chat message', (data) => {

    const room = Array.from(socket.rooms).find(r => r !== socket.id) || 'general';

    io.to(room).emit('chat message', {

      username: socket.username,

      message: data.message,

      timestamp: new Date().toISOString(),

      room: room

    });

  });

});

