    <ul id="user-list">

     <!-- User list will be populated here -->

    </ul>

  </div>

  <div id="chat-area">

    <div id="typing-indicator"></div>

    <div id="messages"></div>

    <form id="form">

     <input id="input" autocomplete="off" placeholder="Type a message..." />

     <button>Send</button>

    </form>

  </div>

</div>

<script>

   // ... existing code ...

   const userList = document.getElementById('user-list');

   const typingIndicator = document.getElementById('typing-indicator');

   const messageInput = document.getElementById('input');

   let typingTimeout;

   // Handle typing events

   messageInput.addEventListener('input', () => {

     // User is typing

     if (!typingTimeout) {

         socket.emit('typing', true);

     }

     // Clear previous timeout

     clearTimeout(typingTimeout);

     // Set a timeout to indicate user stopped typing

     typingTimeout = setTimeout(() => {

         socket.emit('typing', false);

         typingTimeout = null;

     }, 1000);

   });

   // Handle form submission

   form.addEventListener('submit', (e) => {

     e.preventDefault();

     if (messageInput.value.trim()) {

         socket.emit('chat message', {

            message: messageInput.value,

            room: currentRoom

         });

         messageInput.value = '';

         // Clear typing status

         if (typingTimeout) {

            clearTimeout(typingTimeout);

            typingTimeout = null;

            socket.emit('typing', false);

         }

     }

   });

   // Update user list

   socket.on('user list', (data) => {

     if (data.room === currentRoom) {

         userList.innerHTML = '';

         data.users.forEach(user => {

            const userItem = document.createElement('li');

            userItem.textContent = user.username;

            if (user.isTyping) {

               userItem.innerHTML += ' <span class="typing">typing...</span>';

            }

            userList.appendChild(userItem);

         });

     }

   });

   // Update typing indicator

   socket.on('typing users', (usernames) => {

     const typingUsers = usernames.filter(u => u !== currentUsername);

     if (typingUsers.length > 0) {

         typingIndicator.textContent = `${typingUsers.join(', ')} ${typingUsers.length > 1 ? 'are' : 'is'} typing...`;

         typingIndicator.style.display = 'block';

     } else {

         typingIndicator.style.display = 'none';

     }

   });

</script>

<style>

