         color: #666;

         font-style: italic;

         font-size: 0.9em;

         padding: 5px 10px;

         display: none;

   }

   .typing {

         color: #666;

         font-size: 0.8em;

         font-style: italic;

   }

   #user-list {

         list-style: none;

         padding: 0;

         margin: 10px 0;

   }

   #user-list li {

         padding: 5px 10px;

         border-radius: 3px;

         margin: 2px 0;

   }

