Let's create a simple example where the main thread creates a worker to perform a CPU-intensive task:

// main.js

const { Worker } = require('worker_threads');

// Function to create a new worker

function runWorker(workerData) {

  return new Promise((resolve, reject) => {

    // Create a new worker

    const worker = new Worker('./worker.js', { workerData });

    // Listen for messages from the worker

    worker.on('message', resolve);

    // Listen for errors

    worker.on('error', reject);

    // Listen for worker exit

    worker.on('exit', (code) => {

      if (code !== 0) {

        reject(new Error(`Worker stopped with exit code ${code}`));

      }

    });

  });

}

// Run the worker

async function run() {

  try {

    // Send data to the worker and get the result

    const result = await runWorker('Hello from main thread!');

    console.log('Worker result:', result);

  } catch (err) {

    console.error('Worker error:', err);

  }

}

run().catch(err => console.error(err));

// worker.js

const { parentPort, workerData } = require('worker_threads');

// Receive message from the main thread

console.log('Worker received:', workerData);

// Simulate CPU-intensive task

function performCPUIntensiveTask() {

  // Simple example: Sum up to a large number

  let result = 0;

  for (let i = 0; i < 1_000_000; i++) {

    result += i;

  }

  return result;

}

// Perform the task

const result = performCPUIntensiveTask();

// Send the result back to the main thread

parentPort.postMessage({

  receivedData: workerData,

  calculatedSum: result

});

In this example:

 The main thread creates a worker with some initial data

 The worker performs a CPU-intensive calculation

 The worker sends the result back to the main thread

 The main thread receives and processes the result

Key Concepts in the Example

 The Worker constructor takes the path to the worker script and an options object

 The workerData option is used to pass initial data to the worker

 The worker communicates back to the main thread using parentPort.postMessage()

 Event handlers (message, error, exit) are used to manage the worker lifecycle

Worker threads communicate by passing messages.

The communication is bidirectional, meaning both the main thread and workers can send and receive messages.

Main Thread to Worker

// main.js

const { Worker } = require('worker_threads');

// Create a worker

const worker = new Worker('./message_worker.js');

// Send messages to the worker

worker.postMessage('Hello worker!');

worker.postMessage({ type: 'task', data: [1, 2, 3, 4, 5] });

// Receive messages from the worker

worker.on('message', (message) => {

  console.log('Main thread received:', message);

});

// Handle worker completion

worker.on('exit', (code) => {

  console.log(`Worker exited with code ${code}`);

});

// message_worker.js

const { parentPort } = require('worker_threads');

// Receive messages from the main thread

parentPort.on('message', (message) => {

  console.log('Worker received:', message);

  // Process different message types

  if (typeof message === 'object' && message.type === 'task') {

    const result = processTask(message.data);

    parentPort.postMessage({ type: 'result', data: result });

  } else {

    // Echo the message back

    parentPort.postMessage(`Worker echoing: ${message}`);

  }

