// circuit-breaker.js

class CircuitBreaker {

  constructor(request, options = {}) {

    this.request = request;

    this.state = 'CLOSED';

    this.failureCount = 0;

    this.successCount = 0;

    this.nextAttempt = Date.now();

    // Configurable thresholds

    this.failureThreshold = options.failureThreshold || 5;

    this.successThreshold = options.successThreshold || 2;

    this.timeout = options.timeout || 10000; // 10 seconds

  }

  async fire() {

    if (this.state === 'OPEN') {

      if (this.nextAttempt this.successThreshold) {

        this.close();

      }

    }

    this.failureCount = 0;

    return response;

  }

  fail(err) {

    this.failureCount++;

    if (this.failureCount >= this.failureThreshold) {

      this.open();

    }

    return err;

  }

  open() {

    this.state = 'OPEN';

    this.nextAttempt = Date.now() + this.timeout;

  }

  close() {

    this.state = 'CLOSED';

    this.failureCount = 0;

    this.successCount = 0;

    this.nextAttempt = 0;

  }

}

module.exports = CircuitBreaker;

// order-saga.js

class OrderSaga {

  constructor(orderId) {

    this.orderId = orderId;

    this.steps = [];

    this.compensations = [];

  }

  addStep(execute, compensate) {

    this.steps.push(execute);

    this.compensations.unshift(compensate);

    return this;

  }

  async execute() {

    const executedSteps = [];

    try {

      for (const [index, step] of this.steps.entries()) {

        await step();

        executedSteps.push(index);

      }

      return { success: true };

    } catch (error) {

      console.error('Saga execution failed, compensating...', error);

      await this.compensate(executedSteps);

      return { success: false, error };

    }

  }

  async compensate(executedSteps) {

    for (const stepIndex of executedSteps) {

      try {

        await this.compensations[stepIndex]();

      } catch (compError) {

        console.error('Compensation failed:', compError);

      }

    }

  }

}

