The simplest way to use the VM module is to run code in a context:

const vm = require('vm');

// Create a context object

const context = { x: 2 };

// Compile and run a script in the context

vm.createContext(context);

vm.runInContext('x = x * 2; y = 10;', context);

// Inspect the modified context

console.log(context); // Outputs: { x: 4, y: 10 }

In this example:

 We create a context object with a variable x

 We "contextify" this object using vm.createContext()

 We run JavaScript code in this context that modifies x and creates y

 The changes are reflected in the context object

For better performance when executing the same code multiple times, you can pre-compile it using the Script class:

const vm = require('vm');

// Compile the script once

const script = new vm.Script('x += 40; let z = 30;');

// Create multiple contexts

const context1 = { x: 10 };

const context2 = { x: 20 };

// Contextify the objects

vm.createContext(context1);

vm.createContext(context2);

// Run the same script in different contexts

script.runInContext(context1);

script.runInContext(context2);

console.log(context1); // Outputs: { x: 50, z: 30 }

console.log(context2); // Outputs: { x: 60, z: 30 }

Note: Compiling scripts separately is more efficient when you need to execute the same code multiple times, as the parsing and compilation steps happen only once.

1. runInContext
Runs code in a previously created context:

const vm = require('vm');

const context = { value: 10 };

vm.createContext(context);

// Run directly

vm.runInContext('value += 5', context);

console.log(context.value); // 15

// Compile then run

const script = new vm.Script('value *= 2');

script.runInContext(context);

console.log(context.value); // 30

2. runInNewContext
Creates a new context and runs code in it:

const vm = require('vm');

// No need to call createContext first

const context = { value: 10 };

vm.runInNewContext('value += 5; result = value * 2;', context);

console.log(context); // { value: 15, result: 30 }

3. runInThisContext
Runs code in the current V8 context (similar to eval but safer):

const vm = require('vm');

// Define a variable in the current scope

const locallet = 20;

let result;

// This won't have access to localVar

vm.runInThisContext('result = (typeof locallet !== "undefined" ? locallet : "not defined")');

console.log(result); // 'not defined'

// But it can access globals

global.globallet = 30;

vm.runInThisContext('result = globalVar');

console.log(result); // 30

// Compare with eval, which CAN access local variables

eval('result = localVar');

console.log(result); // 20

Note: runInThisContext is similar to eval, but it doesn't have access to local variables in the scope it was called from. This makes it somewhat safer, as it reduces the risk of code injection affecting local variables.

You can set a timeout for script execution to prevent infinite loops or long-running scripts:

const vm = require('vm');

const context = { result: 0 };

vm.createContext(context);

try {

  // This should timeout after 1000ms (1 second)

  vm.runInContext(`

    let counter = 0;

    while (true) {

      counter++;

      result = counter;

    }

  `, context, { timeout: 1000 });

} catch (err) {

  console.error(`Execution timed out: ${err.message}`);

  console.log(`Results before timeout: counter reached ${context.result}`);

}

Warning: The timeout option doesn't guarantee that execution will stop exactly at the specified time. The actual timeout may vary slightly.

By default, code run in VM contexts doesn't have access to Node.js core modules. You can control which modules are available:

const vm = require('vm');

const fs = require('fs');

// Create a sandbox with controlled access to core modules

const sandbox = {

  // Allow limited access to console

  console: {

    log: console.log,

    error: console.error

  },

  // Provide controlled access to fs module

  fs: {

    readFileSync: fs.readFileSync

  },

  // Custom utility

  util: {

    add: (a, b) => a + b,

    multiply: (a, b) => a * b

  },

  // No access to process, child_process, etc.

};

vm.createContext(sandbox);

// Run code with limited access

try {

  vm.runInContext(`

    // We can use the allowed methods

    console.log('Running in sandbox');

    console.log('2 + 3 =', util.add(2, 3));

    // Try to read a safe file

    try {

      const content = fs.readFileSync('example.txt', 'utf8');

      console.log('File content:', content);

    } catch (err) {

      console.error('File read error:', err.message);

    }

    // Try to access process (should fail)

    try {

      console.log('Process info:', process.version);

    } catch (err) {

      console.error('Cannot access process:', err.message);

    }

  `, sandbox);

} catch (err) {

  console.error('Sandbox execution failed:', err);

}

Warning: While you can limit access to certain modules, this approach isn't completely secure. A determined attacker might still find ways to escape the sandbox. For truly secure sandboxing, consider additional isolation techniques or specialized libraries.

The VM module can be used to create a simple template engine:

const vm = require('vm');

function renderTemplate(template, data) {

  // Create template function - replace {{ let }} with values

  const templateScript = `

    function template(data) {

      let output = \`${template.replace(/\{\{\s*(\w+)\s*\}\}/g, '${data.$1}')}\`;

      return output;

    }

    template(data);

  `;

  // Create a context with the data

  const context = { data };

  vm.createContext(context);

  // Execute the template function

  return vm.runInContext(templateScript, context);

}

// Example usage

const template = `

<!DOCTYPE html>

<html>

<head>

  <title>{{ title }}</title>

</head>

<body>

  <h1>{{ title }}</h1>

  <p>Welcome, {{ name }}!</p>

  <p>Today is {{ date }}</p>

</body>

</html>

`;

const data = {

  title: 'My Template Page',

  name: 'User',

  date: new Date().toLocaleDateString()

};

const rendered = renderTemplate(template, data);

console.log(rendered);

Note: While this example demonstrates a simple use case, production template engines like Handlebars or EJS are more robust and secure. This example is vulnerable to injection attacks if user data isn't properly escaped.

The VM module is useful for creating plugin systems where plugins can be loaded and executed in isolation:

const vm = require('vm');

const fs = require('fs');

const path = require('path');

class PluginSystem {

  constructor() {

    this.plugins = new Map();

    this.api = {

      version: '1.0.0',

      registerHook: this.registerHook.bind(this),

      utils: {

        add: (a, b) => a + b,

        multiply: (a, b) => a * b,

        formatDate: (date) => new Date(date).toLocaleDateString()

      }

    };

    this.hooks = {

      init: [],

      process: [],

      shutdown: []

    };

  }

  // Register a plugin hook

  registerHook(hookName, callback) {

    if (this.hooks[hookName]) {

      this.hooks[hookName].push(callback);

      console.log(`Registered ${hookName} hook`);

    } else {

      console.error(`Invalid hook name: ${hookName}`);

    }

  }

  // Load a plugin from file

  loadPlugin(pluginName, pluginCode) {

    try {

      console.log(`Loading plugin: ${pluginName}`);

      // Create a sandbox for this plugin

      const sandbox = {

        console: {

          log: (msg) => console.log(`[${pluginName}] ${msg}`),

          error: (msg) => console.error(`[${pluginName}] ${msg}`)

        },

        setTimeout,

        clearTimeout,

        api: this.api

      };

      // Create context and run the plugin code

      const context = vm.createContext(sandbox);

      vm.runInContext(pluginCode, context);

      // Store the loaded plugin

      this.plugins.set(pluginName, {

        name: pluginName,

        sandbox

      });

      console.log(`Successfully loaded plugin: ${pluginName}`);

    } catch (err) {

      console.error(`Error loading plugin ${pluginName}:`, err.message);

    }

  }

  // Run all hooks of a specific type

  async runHooks(hookName, data) {

    console.log(`Running ${hookName} hooks...`);

    for (const hook of this.hooks[hookName]) {

      try {

        const result = await hook(data);

        console.log(`Hook result:`, result);

      } catch (err) {

        console.error(`Error in ${hookName} hook:`, err.message);

      }

    }

  }

  // Load all plugins from a directory

  loadPluginsFromDirectory(directory) {

    try {

      const files = fs.readdirSync(directory);

      for (const file of files) {

        if (file.endsWith('.js')) {

          const pluginName = path.basename(file, '.js');

          const pluginPath = path.join(directory, file);

          const pluginCode = fs.readFileSync(pluginPath, 'utf8');

          this.loadPlugin(pluginName, pluginCode);

        }

      }

    } catch (err) {

      console.error('Error loading plugins directory:', err.message);

    }

  }

  // Run the plugin system

  async run(data) {

    await this.runHooks('init', data);

    await this.runHooks('process', data);

    await this.runHooks('shutdown', data);

  }

}

// Example plugin code (normally this would be in a separate file)

const examplePlugin = `

// Register initialization hook

api.registerHook('init', async (data) => {

  console.log('Plugin initializing with data:', data);

  return 'Initialization complete';

});

// Register processing hook

api.registerHook('process', async (data) => {

  console.log('Processing data');

  return {

    processed: true,

    sum: api.utils.add(data.x, data.y),

    product: api.utils.multiply(data.x, data.y),

    date: api.utils.formatDate(new Date())

  };

});

// Register shutdown hook

api.registerHook('shutdown', async () => {

  console.log('Plugin shutting down');

  return 'Shutdown complete';

});

console.log('Plugin loaded with API version', api.version);

`;

// Create and run the plugin system

(async () => {

  const system = new PluginSystem();

  // Load plugins

  system.loadPlugin('example', examplePlugin);

  // You could also load from a directory

  // system.loadPluginsFromDirectory('./plugins');

  // Run the system

  await system.run({ x: 5, y: 10 });

})();

Learn how to create and manage complex VM contexts with custom globals and modules:

1. Creating a Custom Context with Global Variables

const vm = require('vm');

const util = require('util');

// Create a custom context with specific global variables

const context = {

  console: {

    log: (...args) => {

      // Custom console.log implementation

      process.stdout.write('Custom Log: ' + util.format(...args) + '\n');

    },

    error: console.error,

    warn: console.warn,

    info: console.info

  },

  // Add custom utilities

  utils: {

    formatDate: () => new Date().toISOString(),

    generateId: () => Math.random().toString(36).substr(2, 9)

  },

  // Add a safe require function

  require: (moduleName) => {

    const allowedModules = ['path', 'url', 'util'];

    if (!allowedModules.includes(moduleName)) {

      throw new Error(`Module '${moduleName}' is not allowed`);

    }

    return require(moduleName);

  }

};

// Contextify the object

vm.createContext(context);

// Run code in the custom context

const code = `

  console.log('Current time:', utils.formatDate());

  console.log('Generated ID:', utils.generateId());

  try {

    const fs = require('fs'); // This will throw an error

  } catch (err) {

    console.error('Security error:', err.message);

  }

  // This will work as it's an allowed module

  const path = require('path');

  console.log('Current directory:', path.dirname('/path/to/file.txt'));

`;

try {

  vm.runInContext(code, context, { filename: 'custom-context.js' });

} catch (err) {

  console.error('Script execution failed:', err);

}

2. Module System in VM
Implement a simple module system within a VM context:

const vm = require('vm');

const fs = require('fs');

const path = require('path');

class VMModuleSystem {

  constructor(basePath = '.') {

    this.basePath = path.resolve(basePath);

    this.cache = new Map();

    this.context = vm.createContext({

      module: { exports: {} },

      exports: {},

      console: console,

      require: this.require.bind(this),

      __dirname: this.basePath,

      __filename: path.join(this.basePath, 'main.js')

    });

  }

  require(modulePath) {

    // Handle core modules

    if (require.resolve.paths(modulePath) === null) {

      return require(modulePath);

    }

    // Resolve the module path

    const resolvedPath = this.resolveModule(modulePath);

    // Check cache

    if (this.cache.has(resolvedPath)) {

      return this.cache.get(resolvedPath).exports;

    }

    // Create new module

    const module = { exports: {} };

    this.cache.set(resolvedPath, module);

    try {

      // Read and execute the module

      const code = fs.readFileSync(resolvedPath, 'utf8');

      const wrapper = `(function(module, exports, require, __dirname, __filename) {${code}\n})`;

      const script = new vm.Script(wrapper, {

        filename: resolvedPath,

        lineOffset: 0,

        displayErrors: true

      });

      const localRequire = (path) => this.require(path);

      localRequire.resolve = (request) => this.resolveModule(request, resolvedPath);

      script.runInNewContext({

        module: module,

        exports: module.exports,

        require: localRequire,

        __dirname: path.dirname(resolvedPath),

        __filename: resolvedPath

      });

      return module.exports;

    } catch (err) {

      this.cache.delete(resolvedPath);

      throw err;

    }

  }

  resolveModule(request, parentPath) {

    try {

      // Try to resolve as a file

      if (request.startsWith('./') || request.startsWith('../')) {

        const resolved = path.resolve(path.dirname(parentPath || this.basePath), request);

        // Try with .js extension

        try {

          const stats = fs.statSync(resolved + '.js');

          if (stats.isFile()) return resolved + '.js';

        } catch (e) {}

        // Try as directory with index.js

        try {

          const indexPath = path.join(resolved, 'index.js');

          const stats = fs.statSync(indexPath);

          if (stats.isFile()) return indexPath;

        } catch (e) {}

        // Try as file without extension

        try {

          const stats = fs.statSync(resolved);

          if (stats.isFile()) return resolved;

        } catch (e) {}

      }

      // Try to resolve as a module

      try {

        return require.resolve(request);

      } catch (e) {

        throw new Error(`Cannot find module '${request}'`);

      }

    } catch (err) {

      throw new Error(`Cannot find module '${request}': ${err.message}`);

    }

  }

  runFile(filePath) {

    const absolutePath = path.resolve(this.basePath, filePath);

    return this.require(absolutePath);

  }

}

// Example usage

const moduleSystem = new VMModuleSystem(__dirname);

try {

  // This will execute the file in the VM with the custom module system

  moduleSystem.runFile('example-module.js');

} catch (err) {

  console.error('Module execution failed:', err);

}

When using the VM module, security should be your top priority. Here are some best practices:

const vm = require('vm');

const { execSync } = require('child_process');

// UNSAFE: Directly executing untrusted code

function unsafeEval(code) {

  // This is dangerous as it has access to the entire Node.js environment

  return vm.runInThisContext(code);

}

// SAFER: Isolated context with limited access

function safeEval(code, timeout = 1000) {

  // Create a context with only the necessary globals

  const context = {

    console: {

      log: console.log,

      error: console.error

    },

    // Add safe utilities

    Math: Object.create(null),

    JSON: {

      parse: JSON.parse,

      stringify: JSON.stringify

    },

    // Add a safe setTimeout with limits

    setTimeout: (fn, delay) => {

      if (delay > 1000) delay = 1000; // Cap delay at 1 second

      return setTimeout(fn, delay);

    }

  };

  // Copy safe methods from Math

  Object.getOwnPropertyNames(Math)

    .filter(prop => typeof Math[prop] === 'function')

    .forEach(prop => {

      context.Math[prop] = Math[prop];

    });

  // Create the context without prototype access

  const sandbox = vm.createContext(context, {

    name: 'sandbox',

    codeGeneration: {

      strings: false,

      wasm: false

    }

  });

  // Run the code with a timeout

  try {

    const script = new vm.Script(`

      (function() {

        "use strict";

        ${code}

      })();

    `, {

      filename: 'sandbox.js',

      lineOffset: 0,

      displayErrors: true,

      timeout: timeout,

      microtaskMode: 'afterEvaluate'

    });

    return script.runInContext(sandbox, { timeout });

  } catch (err) {

    console.error('Script execution failed:', err.message);

    throw new Error('Script execution failed');

  }

}

// Example of safe evaluation

try {

  const result = safeEval(`

    function add(a, b) { return a + b; }

    add(2, 3);

  `);

  console.log('Safe evaluation result:', result); // Outputs: 5

  // This will be caught by our safe evaluator

  safeEval('process.exit(1)');

} catch (err) {

  console.error('Caught error:', err.message);

}

// Example of security risks

console.log('\nTesting security risks:');

try {

  console.log('1. Accessing process:');

  safeEval('process.versions.node');

} catch (err) {

  console.log('✓ Blocked access to process object');

}

try {

  console.log('2. Infinite loop:');

  safeEval('while(true){}');

} catch (err) {

  console.log('✓ Caught infinite loop with timeout');

}

try {

