One of the most common Node.js applications is building RESTful APIs. Here's an example of a simple but practical Todo API with Express:

Example: Todo API with Express

const express = require('express');

const app = express();

// In-memory data store (in a real app, you would use a database)

let todos = [

  { id: 1, title: 'Learn Node.js', completed: false },

  { id: 2, title: 'Build a REST API', completed: false }

];

// Middleware

app.use(express.json());

// Log all requests

app.use((req, res, next) => {

  console.log(`${req.method} ${req.url}`);

  next();

});

// GET all todos

app.get('/todos', (req, res) => {

  res.json(todos);

});

// GET a single todo

app.get('/todos/:id', (req, res) => {

  const todo = todos.find(t => t.id === parseInt(req.params.id));

  if (!todo) return res.status(404).json({ error: 'Todo not found' });

  res.json(todo);

});

// POST a new todo

app.post('/todos', (req, res) => {

  if (!req.body.title) {

    return res.status(400).json({ error: 'Title is required' });

  }

  const newTodo = {

    id: todos.length > 0 ? Math.max(...todos.map(t => t.id)) + 1 : 1,

    title: req.body.title,

    completed: req.body.completed || false

  };

  todos.push(newTodo);

  res.status(201).json(newTodo);

});

// PUT (update) a todo

app.put('/todos/:id', (req, res) => {

  const todo = todos.find(t => t.id === parseInt(req.params.id));

  if (!todo) return res.status(404).json({ error: 'Todo not found' });

  if (req.body.title) todo.title = req.body.title;

  if (req.body.completed !== undefined) todo.completed = req.body.completed;

  res.json(todo);

});

// DELETE a todo

app.delete('/todos/:id', (req, res) => {

  const index = todos.findIndex(t => t.id === parseInt(req.params.id));

  if (index === -1) return res.status(404).json({ error: 'Todo not found' });

  const deletedTodo = todos[index];

  todos.splice(index, 1);

  res.json(deletedTodo);

});

// Error handling middleware

app.use((err, req, res, next) => {

  console.error(err.stack);

  res.status(500).json({ error: 'Something went wrong!' });

});

// Start the server

const PORT = process.env.PORT || 8080;

app.listen(PORT, () => {

  console.log(`Server running on port ${PORT}`);

});

This example demonstrates a complete CRUD (Create, Read, Update, Delete) API with proper error handling and status codes.

Most applications need authentication. Here's an example of JWT-based authentication in Node.js:

Example: JWT Authentication with Express

const express = require('express');

const jwt = require('jsonwebtoken');

const bcrypt = require('bcrypt');

const app = express();

app.use(express.json());

// In a real app, use a database

const users = [];

// Secret key for JWT

const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key';

// Register a new user

app.post('/register', async (req, res) => {

  try {

    const { username, password } = req.body;

    // Check if user already exists

    if (users.find(u => u.username === username)) {

      return res.status(400).json({ error: 'Username already exists' });

    }

    // Hash the password

    const hashedPassword = await bcrypt.hash(password, 10);

    // Create new user

    const user = {

      id: users.length + 1,

      username,

      password: hashedPassword

    };

    users.push(user);

    res.status(201).json({ message: 'User registered successfully' });

  } catch (error) {

