Node.js makes it easy to handle file uploads, which is common in many web applications:

Example: File Upload with Express and Multer

const express = require('express');

const multer = require('multer');

const path = require('path');

const fs = require('fs');

const app = express();

app.use(express.json());

app.use(express.static('public'));

// Configure multer storage

const storage = multer.diskStorage({

  destination: (req, file, cb) => {

    const uploadDir = './uploads';

    // Create directory if it doesn't exist

    if (!fs.existsSync(uploadDir)) {

      fs.mkdirSync(uploadDir);

    }

    cb(null, uploadDir);

  },

  filename: (req, file, cb) => {

    // Generate unique filename with original extension

    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);

    const ext = path.extname(file.originalname);

    cb(null, file.fieldname + '-' + uniqueSuffix + ext);

  }

});

// File filter function

const fileFilter = (req, file, cb) => {

  // Accept images and PDFs only

  if (file.mimetype.startsWith('image/') || file.mimetype === 'application/pdf') {

    cb(null, true);

  } else {

    cb(new Error('Unsupported file type'), false);

  }

};

const upload = multer({ 

  storage: storage,

  fileFilter: fileFilter,

  limits: { fileSize: 5 * 1024 * 1024 } // 5MB limit

});

// Serve upload form

app.get('/', (req, res) => {

  res.sendFile(path.join(__dirname, 'public', 'index.html'));

});

// Single file upload endpoint

app.post('/upload/single', upload.single('file'), (req, res) => {

  if (!req.file) {

    return res.status(400).json({ error: 'No file uploaded' });

  }

  res.json({

    message: 'File uploaded successfully',

    file: {

      filename: req.file.filename,

      originalname: req.file.originalname,

      mimetype: req.file.mimetype,

      size: req.file.size

    }

  });

});

// Multiple file upload endpoint (max 5)

app.post('/upload/multiple', upload.array('files', 5), (req, res) => {

  if (!req.files || req.files.length === 0) {

    return res.status(400).json({ error: 'No files uploaded' });

  }

  res.json({

    message: `${req.files.length} files uploaded successfully`,

    files: req.files.map(file => ({

      filename: file.filename,

      originalname: file.originalname,

      mimetype: file.mimetype,

      size: file.size

    }))

  });

});

// Error handling middleware

app.use((err, req, res, next) => {

  if (err instanceof multer.MulterError) {

    // Multer-specific errors

    return res.status(400).json({ error: err.message });

  } else if (err) {

    // Other errors

    return res.status(500).json({ error: err.message });

  }

  next();

});

app.listen(8080, () => {

  console.log('File upload server running on port 8080');

});

